-- Packages for "Komfort Plus 4K"

INSERT INTO tv_channel_packages (service_id, name, monthly_fee, is_base_package)
SELECT service_id, 'Podstawowy', 0.00, true
FROM service_translations WHERE language_code = 'pl' AND name = 'Komfort Plus 4K' LIMIT 1;
INSERT INTO tv_channel_package_translations (language_code, tv_channel_package_id, name)
VALUES ('pl', currval('tv_service_offers_id_seq'), 'Podstawowy');
INSERT INTO tv_channel_package_translations (language_code, tv_channel_package_id, name)
VALUES ('en', currval('tv_service_offers_id_seq'), 'Basic');
INSERT INTO tv_channel_offers (tv_service_id, tv_channel_id)
SELECT currval('tv_service_offers_id_seq'), tc.id
FROM tv_channels tc JOIN tv_channel_translations t ON t.tv_channel_id = tc.id AND t.language_code = 'pl'
WHERE t.name IN ('TVP 1', 'TVP 2', 'Polsat', 'TVN');

