-- Documents INSERT INTO document_translations (language_code, document_id, name, text) SELECT 'fr', document_id, CASE name WHEN 'Document 1' THEN 'Document 1' ELSE name END, 'Contenu du document 1 depuis ''assets'' Deuxième ligne du document 1' FROM document_translations WHERE language_code = 'en';
-- Services INSERT INTO service_translations (service_id, language_code, name, info) SELECT service_id, 'fr', CASE name WHEN '600/120 Mb/s' THEN '600/120 Mb/s' WHEN 'Komfort Plus 4K' THEN 'Confort Plus 4K' WHEN '20 nagran / 60 dni' THEN '20 enregistrements / 60 jours' WHEN 'No limit 56' THEN 'Illimité 56' WHEN 'Inna usługa' THEN 'Autre service' WHEN '1000GB' THEN '1000 Go' WHEN 'Telewizja standard' THEN 'Télévision standard' WHEN 'Internet 100 Mb/s' THEN 'Internet 100 Mb/s' WHEN 'Pakiet TV Basic' THEN 'Pack TV Basic' WHEN 'Telefon VoIP' THEN 'Téléphone VoIP' WHEN 'Internet 300 Mb/s' THEN 'Internet 300 Mb/s' WHEN 'Telewizja Premium 4K' THEN 'Télévision Premium 4K' WHEN 'Mobile Start' THEN 'Mobile Start' WHEN 'Pakiet Sport' THEN 'Pack Sport' WHEN 'Statyczne IP' THEN 'IP statique' ELSE name END, CASE name WHEN '600/120 Mb/s' THEN 'Envoi : jusqu''à 120 Mb/s, Téléchargement : jusqu''à 600 Mb/s' WHEN 'Komfort Plus 4K' THEN '128 chaînes 4K' WHEN '20 nagran / 60 dni' THEN 'Pack d''enregistrement dans le cloud' WHEN 'No limit 56' THEN 'Appels et SMS illimités' WHEN 'Inna usługa' THEN 'Service supplémentaire' WHEN '1000GB' THEN 'Pack data mobile 1000 Go' WHEN 'Telewizja standard' THEN 'Pack TV de base' WHEN 'Internet 100 Mb/s' THEN 'Internet fibre rapide 100 Mb/s' WHEN 'Pakiet TV Basic' THEN 'Pack TV câble basique' WHEN 'Telefon VoIP' THEN 'Téléphonie internet VoIP' WHEN 'Internet 300 Mb/s' THEN 'Fibre internet milieu de gamme 300 Mb/s' WHEN 'Telewizja Premium 4K' THEN 'Plus de 200 chaînes, dont sport et cinéma premium en 4K' WHEN 'Mobile Start' THEN '5 Go de données, 100 minutes d''appels' WHEN 'Pakiet Sport' THEN 'Chaînes sportives supplémentaires' WHEN 'Statyczne IP' THEN 'Adresse IPv4 publique dédiée' ELSE info END FROM service_translations WHERE language_code = 'pl';
-- TV channels (names mostly identical, but normalize a few) INSERT INTO tv_channel_translations (language_code, tv_channel_id, name) SELECT 'fr', tv_channel_id, name FROM tv_channel_translations WHERE language_code = 'pl';
-- TV channel packages INSERT INTO tv_channel_package_translations (language_code, tv_channel_package_id, name) SELECT 'fr', tv_channel_package_id, CASE name WHEN 'Podstawowy' THEN 'De base' WHEN 'Sport+' THEN 'Sport+' WHEN 'Filmy+' THEN 'Films+' WHEN 'Dla dzieci' THEN 'Pour enfants' WHEN 'Pakiet podstawowy' THEN 'Pack de base' WHEN 'Rozszerzony' THEN 'Étendu' ELSE name END FROM tv_channel_package_translations WHERE language_code = 'pl';
-- Consent types INSERT INTO consent_type_translations (language_code, consent_type_id, code, description) SELECT 'fr', consent_type_id, code, CASE code WHEN 'MARKETING' THEN 'Consentement à la communication marketing' ELSE description END FROM consent_type_translations WHERE language_code = 'en';

