-- Modem światłowodowy INSERT INTO hardware (image_path, is_returnable, is_reportable) VALUES ('http://localhost:8080/hardware/fiber-modem.jpg', true, true); INSERT INTO hardware_translations (language_code, hardware_id, name) VALUES ('pl', currval('hardware_id_seq'), 'Modem światłowodowy'), ('en', currval('hardware_id_seq'), 'Fiber modem'), ('fr', currval('hardware_id_seq'), 'Modem fibre');
-- Dekoder 4K INSERT INTO hardware (image_path, is_returnable, is_reportable) VALUES ('http://localhost:8080/hardware/decoder-4k.jpg', true, true); INSERT INTO hardware_translations (language_code, hardware_id, name) VALUES ('pl', currval('hardware_id_seq'), 'Dekoder 4K'), ('en', currval('hardware_id_seq'), '4K Set-top box'), ('fr', currval('hardware_id_seq'), 'Décodeur 4K');
-- Dekoder 4K Hybrid INSERT INTO hardware (image_path, is_returnable, is_reportable) VALUES ('http://localhost:8080/hardware/decoder-4k-hybrid.jpg', true, true); INSERT INTO hardware_translations (language_code, hardware_id, name) VALUES ('pl', currval('hardware_id_seq'), 'Dekoder 4K Hybrid'), ('en', currval('hardware_id_seq'), '4K Hybrid Set-top box'), ('fr', currval('hardware_id_seq'), 'Décodeur 4K Hybride');
