-- Link hardware to compatible services via services_hardware INSERT INTO services_hardware (service_id, hardware_id) SELECT st.service_id, ht.hardware_id FROM service_translations st, hardware_translations ht WHERE st.language_code = 'pl' AND ht.language_code = 'pl' AND ( (st.name IN ('600/120 Mb/s', 'Internet 100 Mb/s', 'Internet 300 Mb/s') AND ht.name IN ('Router Wi-Fi 6', 'Modem światłowodowy')) OR (st.name IN ('Komfort Plus 4K', 'Telewizja Premium 4K') AND ht.name = 'Dekoder 4K Hybrid') OR (st.name = 'Telewizja standard' AND ht.name = 'Dekoder 4K') OR (st.name = 'Pakiet TV Basic' AND ht.name = 'Dekoder 4K') OR (st.name = 'Telefon VoIP' AND ht.name = 'Telefon VoIP') OR (st.name IN ('No limit 56', '1000GB', 'Mobile Start') AND ht.name = 'Karta SIM') );

