    ('pl', currval('notification_types_id_seq'), 'Alert bezpieczeństwa'),
    ('en', currval('notification_types_id_seq'), 'Security alert'),
    ('fr', currval('notification_types_id_seq'), 'Alerte de sécurité');

INSERT INTO notification_types (code) VALUES ('CONTRACT_EXPIRING');
INSERT INTO notification_type_translations (language_code, notification_type_id, name) VALUES
    ('pl', currval('notification_types_id_seq'), 'Wygasająca umowa'),
    ('en', currval('notification_types_id_seq'), 'Contract expiring'),
    ('fr', currval('notification_types_id_seq'), 'Contrat arrivant à échéance');

-- Router Wi-Fi 6 → C001's active fiber service on Marszałkowska INSERT INTO client_hardware (hardware_id, client_service_id, ownership, serial_number) SELECT (SELECT h.id FROM hardware h JOIN hardware_translations ht ON ht.hardware_id = h.id WHERE ht.language_code = 'pl' AND ht.name = 'Router Wi-Fi 6' LIMIT 1), cs.id, 'RENTED', 'WIFI6-MARSZ-001' FROM client_services cs JOIN service_translations st ON st.service_id = cs.service_id AND st.language_code = 'pl' JOIN clients c ON c.id = cs.client_id JOIN client_addresses ca ON ca.id = cs.address_id WHERE c.client_number = 'C001' AND st.name = 'Internet 100 Mb/s' AND ca.address LIKE '%Marszałkowska%' LIMIT 1;
-- Dekoder 4K Hybrid → Komfort Plus 4K INSERT INTO client_hardware (hardware_id, client_service_id, ownership, serial_number) SELECT (SELECT h.id FROM hardware h JOIN hardware_translations ht ON ht.hardware_id = h.id WHERE ht.language_code = 'pl' AND ht.name = 'Dekoder 4K Hybrid' LIMIT 1), cs.id, 'RENTED', 'STB4K-HYB-002' FROM client_services cs JOIN service_translations st ON st.service_id = cs.service_id AND st.language_code = 'pl' JOIN clients c ON c.id = cs.client_id WHERE c.client_number = 'C001' AND st.name = 'Komfort Plus 4K' AND cs.status = 'Active' LIMIT 1;
-- Telefon VoIP → C001's VoIP service INSERT INTO client_hardware (hardware_id, client_service_id, ownership, serial_number) SELECT (SELECT h.id FROM hardware h JOIN hardware_translations ht ON ht.hardware_id = h.id WHERE ht.language_code = 'pl' AND ht.name = 'Telefon VoIP' LIMIT 1), cs.id, 'OWNED', 'VOIP-PH-003' FROM client_services cs JOIN service_translations st ON st.service_id = cs.service_id AND st.language_code = 'pl' JOIN clients c ON c.id = cs.client_id WHERE c.client_number = 'C001' AND st.name = 'Telefon VoIP' LIMIT 1;
-- Karta SIM → 1000GB on Długa INSERT INTO client_hardware (hardware_id, client_service_id, ownership, serial_number) SELECT (SELECT h.id FROM hardware h JOIN hardware_translations ht ON ht.hardware_id = h.id WHERE ht.language_code = 'pl' AND ht.name = 'Karta SIM' LIMIT 1), cs.id, 'OWNED', 'SIM-1000GB-004' FROM client_services cs JOIN service_translations st ON st.service_id = cs.service_id AND st.language_code = 'pl' JOIN clients c ON c.id = cs.client_id JOIN client_addresses ca ON ca.id = cs.address_id WHERE c.client_number = 'C001' AND st.name = '1000GB' AND ca.address LIKE '%Długa%' LIMIT 1;
-- Modem światłowodowy → C001's fiber service INSERT INTO client_hardware (hardware_id, client_service_id, ownership, serial_number) SELECT (SELECT h.id FROM hardware h JOIN hardware_translations ht ON ht.hardware_id = h.id WHERE ht.language_code = 'pl' AND ht.name = 'Modem światłowodowy' LIMIT 1), cs.id, 'RENTED', 'FIBER-MOD-005' FROM client_services cs JOIN service_translations st ON st.service_id = cs.service_id AND st.language_code = 'pl' JOIN clients c ON c.id = cs.client_id WHERE c.client_number = 'C001' AND st.name = 'Internet 100 Mb/s' LIMIT 1;

-- Ensure invoices from previous changeset are paid UPDATE invoices SET status = 'PAID' WHERE invoice_number IN ('FV/2023/01/10001/23', 'FV/2024/01/10002/23');
-- Matching payments INSERT INTO payments (amount, payment_date, payment_method, transaction_id, title, client_id, invoice_id) SELECT i.total_amount, i.due_date - INTERVAL '2 days', 'CARD', 'TX-' || i.invoice_number, 'Płatność za fakturę ' || i.invoice_number, i.client_id, i.id FROM invoices i WHERE i.invoice_number IN ('FV/2023/01/10001/23', 'FV/2024/01/10002/23');
-- One standalone top-up payment (no linked invoice) INSERT INTO payments (amount, payment_date, payment_method, transaction_id, title, client_id, invoice_id) VALUES ( 50.00, CURRENT_TIMESTAMP - INTERVAL '10 days', 'BLIK', 'TX-TOPUP-001', 'Doładowanie konta', (SELECT id FROM clients WHERE client_number = 'C001'), NULL );
-- A partial refund on the oldest paid invoice (service credit) INSERT INTO refunds (amount, refund_date, status, reason, payment_id) SELECT 45.50, p.payment_date + INTERVAL '5 days', 'COMPLETED', 'Zwrot za przerwę w dostępie do usługi', p.id FROM payments p JOIN invoices i ON i.id = p.invoice_id WHERE i.invoice_number = 'FV/2023/01/10001/23';

-- C001 ordered 3 different offer variants over time INSERT INTO offer_orders (client_id, offer_variant_id, ordered_at) SELECT c.id, ov.id, NOW() - INTERVAL '180 days' FROM clients c, offer_variants ov JOIN offers o ON o.id = ov.offer_id WHERE c.client_number = 'C001' AND o.title = 'Internet 1Gb/s' AND ov.name = '1 Gb/s 24M' LIMIT 1;
INSERT INTO offer_orders (client_id, offer_variant_id, ordered_at) SELECT c.id, ov.id, NOW() - INTERVAL '90 days' FROM clients c, offer_variants ov JOIN offers o ON o.id = ov.offer_id WHERE c.client_number = 'C001' AND o.title = 'Pakiet TV Komfort 4K' AND ov.name = 'Komfort 4K 24M' LIMIT 1;
INSERT INTO offer_orders (client_id, offer_variant_id, ordered_at) SELECT c.id, ov.id, NOW() - INTERVAL '14 days' FROM clients c, offer_variants ov JOIN offers o ON o.id = ov.offer_id WHERE c.client_number = 'C001' AND o.title = 'Router Wi-Fi 6' AND ov.name = 'Router Wi-Fi 6 jednorazowo' LIMIT 1;

INSERT INTO document_translations (language_code, document_id, name, text) SELECT 'fr', en.document_id, en.name, en.text FROM document_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM document_translations fr WHERE fr.language_code = 'fr' AND fr.document_id = en.document_id);
INSERT INTO service_translations (service_id, language_code, name, info) SELECT en.service_id, 'fr', en.name, en.info FROM service_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM service_translations fr WHERE fr.language_code = 'fr' AND fr.service_id = en.service_id);
INSERT INTO tv_channel_translations (language_code, tv_channel_id, name) SELECT 'fr', en.tv_channel_id, en.name FROM tv_channel_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM tv_channel_translations fr WHERE fr.language_code = 'fr' AND fr.tv_channel_id = en.tv_channel_id);
INSERT INTO tv_channel_package_translations (language_code, tv_channel_package_id, name) SELECT 'fr', en.tv_channel_package_id, en.name FROM tv_channel_package_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM tv_channel_package_translations fr WHERE fr.language_code = 'fr' AND fr.tv_channel_package_id = en.tv_channel_package_id);
INSERT INTO consent_type_translations (language_code, consent_type_id, code, description) SELECT 'fr', en.consent_type_id, en.code, en.description FROM consent_type_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM consent_type_translations fr WHERE fr.language_code = 'fr' AND fr.consent_type_id = en.consent_type_id);
INSERT INTO notification_type_translations (language_code, notification_type_id, name) SELECT 'fr', en.notification_type_id, en.name FROM notification_type_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM notification_type_translations fr WHERE fr.language_code = 'fr' AND fr.notification_type_id = en.notification_type_id);
INSERT INTO hardware_translations (language_code, hardware_id, name) SELECT 'fr', en.hardware_id, en.name FROM hardware_translations en WHERE en.language_code = 'en' AND NOT EXISTS (SELECT 1 FROM hardware_translations fr WHERE fr.language_code = 'fr' AND fr.hardware_id = en.hardware_id);

